using Niedax.AX.Security;

public class NDXRoleTable extends common
{
}

Method.Source:
/// <summary>
/// PaffH 18.01.21
/// find role by roleIdentifier
/// </summary>
/// <param name = "_RoleIdentifier">NDXRoleIdentifier</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXRoleTable</returns>
static public NDXRoleTable find(NDXRoleIdentifier _RoleIdentifier,
    boolean _forUpdate = false)
{
    NDXRoleTable   nDXRoleTable;

    nDXRoleTable.selectForUpdate(_forUpdate);

    select firstonly nDXRoleTable
        where nDXRoleTable.RoleIdentifier == _RoleIdentifier;
    return nDXRoleTable;
}

/// <summary>
/// PaffH 18.01.21
/// find or create NDXRoleTable
/// </summary>
/// <param name = "_RoleIdentifier">NDXRoleIdentifier</param>
/// <param name = "_insertNewRecord">boolean</param>
/// <returns>NDXRoleTable</returns>
static public NDXRoleTable findOrCreate(NDXRoleIdentifier _RoleIdentifier,
    boolean _insertNewRecord = true)
{
    NDXRoleTable   nDXRoleTable;
    nDXRoleTable = NDXRoleTable::find(_RoleIdentifier, true);
    if (!nDXRoleTable)
    {
        nDXRoleTable.RoleIdentifier = _RoleIdentifier;
        if (_insertNewRecord)
        {
            nDXRoleTable.insert();
        }
    }
    return nDXRoleTable;
}

/// <summary>
/// PaffH 18.01.21
/// save NDXRole from nDXRole-object
/// </summary>
/// <param name = "nDXRole">NDXRole object</param>
/// <param name = "updatedUtcDateTime">update time stamp</param>
/// <returns>record is new</returns>
static public NDXRoleTable saveFromNDXRole(NDXRole nDXRole, NDXUpdatedUTCDateTime updatedUtcDateTime)
{
    NDXRoleTable nDXRoleTable;
    nDXRoleTable = NDXRoleTable::findOrCreate(nDXRole.Role.Identifier, false);
    nDXRoleTable.UpdatedUTCDateTime = updatedUtcDateTime;
    nDXRoleTable.RoleName = nDXRole.Role.Name;
    //nDXRole.Role.Identifier
    nDXRoleTable.Description = nDXRole.Role.Description;
    if (nDXRoleTable.validateWrite())
    {
        ttsbegin;
        nDXRoleTable.write();
        ttscommit;
    }
    return nDXRoleTable;
}

/// <summary>
/// PaffH 20.01.21
/// delete records not updated
/// </summary>
/// <param name = "_updatedUtcDateTime">NDXUpdatedUTCDateTime</param>
/// <param name = "_logger">NDXLoggerSecurityInformationClass</param>
/// <returns>counter deleted records</returns>
static public int deleteNotUpdated(NDXUpdatedUTCDateTime _updatedUtcDateTime, NDXLoggerSecurityInformationClass _logger)
{
    NDXRoleTable nDXRoleTable;
    NDXArgsLoggerSecuritiyInformation argsLogger = new NDXArgsLoggerSecuritiyInformation();
    argsLogger.parmLogActivity(strFmt("@NDX:NDXDeleteRecordsInTable", tableId2PName(nDXRoleTable.TableId)));
    _logger.LogLineCreate(argsLogger);

    NDXHelperTable::skipForDelete(nDXRoleTable);
    delete_from nDXRoleTable
        where nDXRoleTable.UpdatedUTCDateTime != _updatedUtcDateTime;

    argsLogger.parmCounter(int642int(nDXRoleTable.RowCount()));
    _logger.LogLineChange(argsLogger);

    return int642int(nDXRoleTable.RowCount());
}
